<?php
$page_title='Manage Session'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../config/session.php'; require_once __DIR__.'/../../config/functions.php'; require_once __DIR__.'/../../config/auth.php'; requireAdmin(); $id=(int)($_GET['id']??$_POST['id']??0); $session=null;if($id){$stmt=$pdo->prepare('SELECT * FROM sessions WHERE id=?');$stmt->execute([$id]);$session=$stmt->fetch();if(!$session){header('Location: index.php');exit;}}$mentors=$pdo->query("SELECT id,full_name FROM users WHERE role='mentor' AND is_active=1 ORDER BY full_name")->fetchAll();$courses=$pdo->query("SELECT id,title FROM courses ORDER BY title")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??'');$mentor=(int)($_POST['mentor_id']??0);$course=(int)($_POST['course_id']??0);$scheduled=$_POST['scheduled_at']??'';$description=trim($_POST['description']??'');$duration=(int)($_POST['duration']??60);$capacity=(int)($_POST['max_participants']??50);$link=trim($_POST['meeting_link']??'');$status=$_POST['status']??'scheduled';$price=(float)($_POST['price']??0);$free=isset($_POST['is_free'])?1:0;if($title&&$mentor&&$scheduled){if($id){$stmt=$pdo->prepare('UPDATE sessions SET mentor_id=?,course_id=?,title=?,description=?,scheduled_at=?,duration=?,max_participants=?,meeting_link=?,status=?,price=?,is_free=? WHERE id=?');$stmt->execute([$mentor,$course?:null,$title,$description,$scheduled,$duration,$capacity,$link,$status,$price,$free,$id]);}else{$stmt=$pdo->prepare('INSERT INTO sessions (mentor_id,course_id,title,description,scheduled_at,duration,max_participants,meeting_link,status,price,is_free) VALUES (?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$mentor,$course?:null,$title,$description,$scheduled,$duration,$capacity,$link,$status,$price,$free]);}$target=$id?:$pdo->lastInsertId();header('Location: manage.php?id='.$target);exit;}}
?>
<?php include __DIR__.'/../includes/header.php'; ?><div class="admin-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><main class="admin-main"><div class="admin-topbar"><div><h1 class="admin-title"><?php echo $id?'Manage session':'Create session'; ?></h1><p class="admin-subtitle">Keep the schedule and access details accurate for learners.</p></div><a class="btn btn-outline-secondary" href="index.php">Back</a></div><div class="admin-card"><form method="POST"><input type="hidden" name="id" value="<?php echo $id; ?>"><div class="admin-form-grid"><div class="full"><label>Title</label><input name="title" required value="<?php echo htmlspecialchars($session['title']??''); ?>"></div><div><label>Mentor</label><select name="mentor_id" required><option value="">Select mentor</option><?php foreach($mentors as $mentor): ?><option value="<?php echo $mentor['id']; ?>" <?php echo (($session['mentor_id']??0)==$mentor['id'])?'selected':''; ?>><?php echo htmlspecialchars($mentor['full_name']); ?></option><?php endforeach; ?></select></div><div><label>Course</label><select name="course_id"><option value="">General session</option><?php foreach($courses as $course): ?><option value="<?php echo $course['id']; ?>" <?php echo (($session['course_id']??0)==$course['id'])?'selected':''; ?>><?php echo htmlspecialchars($course['title']); ?></option><?php endforeach; ?></select></div><div><label>Scheduled at</label><input type="datetime-local" name="scheduled_at" required value="<?php echo $session ? date('Y-m-d\TH:i',strtotime($session['scheduled_at'])) : ''; ?>"></div><div><label>Status</label><select name="status"><?php foreach(['scheduled','ongoing','completed','cancelled'] as $status): ?><option value="<?php echo $status; ?>" <?php echo (($session['status']??'scheduled')===$status)?'selected':''; ?>><?php echo ucfirst($status); ?></option><?php endforeach; ?></select></div><div><label>Duration (minutes)</label><input type="number" min="1" name="duration" value="<?php echo $session['duration']??60; ?>"></div><div><label>Maximum participants</label><input type="number" min="1" name="max_participants" value="<?php echo $session['max_participants']??50; ?>"></div><div><label>Price</label><input type="number" min="0" step="0.01" name="price" value="<?php echo $session['price']??0; ?>"></div><div><label>Meeting link</label><input type="url" name="meeting_link" value="<?php echo htmlspecialchars($session['meeting_link']??''); ?>"></div><div><label><input type="checkbox" name="is_free" <?php echo (($session['is_free']??0)?'checked':''); ?>> Free session</label></div><div class="full"><label>Description</label><textarea name="description"><?php echo htmlspecialchars($session['description']??''); ?></textarea></div></div><button class="btn btn-primary mt-3"><i class="fas fa-save"></i> Save session</button></form></div></main></div><?php include __DIR__.'/../includes/footer.php'; ?>
